\label{tab:judge_severity}
\small
\begin{tabular}{lcc}
\toprule
Judge & $d_j$ (mean) & 95\% CI \\
\midrule
GPT-5.5 & $-$0.83 & [$-$1.02, $-$0.64] \\
Claude Opus 4.7 & $-$0.31 & [$-$0.48, $-$0.14] \\
Claude Sonnet 4.6 & $-$0.12 & [$-$0.29, +0.05] \\
